def download(remote_location, remotes=None, prefix="", dry_run=False):
    """
    Download resources from a stage server.
    """
    if remotes is None:
        remotes = []
    remotes = [prefix + remote_location] + remotes
    for remote in remotes:
        if not dry_run:
            print("Downloading %s" % remote)
            urllib.request.urlretrieve(remote, remote)
        else:
            print("Would download %s" % remote)

